-- 2025 Woodridge Dual: DB times were truncated to whole seconds; take the scorer sheet's value (scan_ggucker_2025-04-15). Old values in BRAIN.md [C105]. Id-independent; re-runnable (matches on the old time).
SET QUOTED_IDENTIFIER ON;
SET XACT_ABORT ON;
BEGIN TRANSACTION;
DECLARE @m INT, @n INT;
SET @m = (SELECT TOP 1 Id FROM Meets WHERE Name=N'2025 Woodridge Dual' AND CAST(Date AS date)='2025-04-15');
IF @m IS NULL THROW 50070, 'meet missing', 1;
UPDATE p SET p.TimeSeconds=310.7 FROM Performances p JOIN Athletes a ON a.Id=p.AthleteId JOIN Events e ON e.Id=p.EventId WHERE p.MeetId=@m AND a.FirstName+N' '+a.LastName=N'Austin McNeal' AND e.Gender=1 AND e.Name=N'1600M' AND ABS(p.TimeSeconds-310.0)<0.006;
SET @n = @@ROWCOUNT; IF @n > 1 THROW 50071, 'more than one row matched', 1;
